```c
#include <poll.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <fcntl.h>
#include <errno.h>

int connect_with_timeout(int sockfd, struct sockaddr *addr, socklen_t addrlen, int timeout_ms) {
    // Set socket to non-blocking
    int flags = fcntl(sockfd, F_GETFL, 0);
    fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

    // Initiate connection
    int ret = connect(sockfd, addr, addrlen);
    if (ret == 0) {
        // Connection completed immediately
        return 0;
    }
    if (ret < 0 && errno != EINPROGRESS) {
        // Real error occurred
        return -1;
    }

    // Connection is in progress, wait using poll
    struct pollfd pfd;
    pfd.fd = sockfd;
    pfd.events = POLLOUT;  // Wait for writability

    ret = poll(&pfd, 1, timeout_ms);
    if (ret == 0) {
        // Timeout
        errno = ETIMEDOUT;
        return -1;
    }
    if (ret < 0) {
        // Poll error
        return -1;
    }

    // Check if connection succeeded
    int error;
    socklen_t len = sizeof(error);
    if (getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &error, &len) < 0) {
        return -1;
    }
    if (error) {
        errno = error;
        return -1;
    }

    // Connection successful
    return 0;
}
```

Key points about this implementation:

1. First, set the socket to non-blocking mode using `fcntl()`
2. Initiate the connection with `connect()`
3. Use `poll()` to wait for the socket to become writable
4. After `poll()` returns, check the actual connection status using `getsockopt()`

Usage example:

```c
