    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {
        .sin_family = AF_INET,
        .sin_port = htons(80),
        .sin_addr.s_addr = /* target IP */
    };

    // Try to connect with 5 second timeout
    if (connect_with_timeout(sockfd, (struct sockaddr*)&addr, sizeof(addr), 5000) < 0) {
        perror("Connection failed");
        return 1;
    }

    printf("Connected successfully\n");
    return 0;
}
```

The advantage of using `poll()` over blocking connect is that you can:
- Set a timeout for the connection attempt
- Handle multiple connection attempts simultaneously
- Cancel connection attempts
- Avoid blocking the entire program while waiting

Note that you can also use `select()` instead of `poll()`, but `poll()` is generally preferred as it's more efficient and doesn't have the file descriptor number limitations that `select()` has.

