    public void start(Stage stage) throws IOException {

        File file = new File("../images/picture.bmp");

        byte[] header = new byte[14];
        byte[] dib_headerSize = new byte[4];
        byte[] dib_header = new byte[40];

        int width, heigth, bPp; //bytes per pixel

        Group root = new Group();

        try {
            BufferedInputStream bufferedInputStream = new BufferedInputStream(new FileInputStream(file));

            bufferedInputStream.read(header);
            bufferedInputStream.read(dib_headerSize);
            bufferedInputStream.read(dib_header);

            width = bytesTools.calcWidth(dib_header);
            heigth = bytesTools.calcHeight(dib_header);

            bPp = Integer.decode(bytesTools.bytesToString(bytesTools.toBigEndian(dib_header, 10, 12))) / 8;

            byte[] pixel = new byte[bPp];

