                if(x%RESOLUTION == 0){
                    if(!isWhite(pixel)){
                        Rectangle rectangle = new Rectangle(1, 1);
                        rectangle.setX(x/RESOLUTION);
                        rectangle.setY(y/RESOLUTION);
                        bytesTools.showBytes(pixel);

                        rectangle.setFill(Color.color(Byte.toUnsignedInt(pixel[1])/255f, Byte.toUnsignedInt(pixel[0])/255f, Byte.toUnsignedInt(pixel[2])/255f));
                        root.getChildren().add(rectangle);
                    }
                }
                ++x;

                if(x == width){
                    --y;
                    x=0;
                }
            }

        } catch (IOException e) {
            throw new RuntimeException(e);
        }

        Scene scene = new Scene(root, width/RESOLUTION, heigth/RESOLUTION);

        stage.setTitle("PictureTool");
        stage.setScene(scene);
        stage.show();
    }

