        for(byte var : pixel){
            if(Byte.toUnsignedInt(var) != 255){
                return false;
            }
        }
        return true;
    }
}
package org.example.bitmap;

public class BytesTools {

    private static final BytesTools INSTANCE = new BytesTools();

    private BytesTools(){}

    public int calcWidth(byte[] bytes){return Integer.decode(bytesToString(toBigEndian(bytes, 0, 4)));}

    public int calcHeight(byte[] bytes){return Integer.decode(bytesToString(toBigEndian(bytes, 4, 8)));}

    public byte[] toBigEndian(byte[] bytes, int start, int end){
        byte[] bigEndian = new byte[end-start];

        for(int i = start; i<end; ++i){
            bigEndian[(end-1) - i] = bytes[i];
        }

        return bigEndian;
    }

    public String bytesToString(byte[] bytes){
        String Sbytes = "0x";

        for(int i = 0; i<bytes.length; ++i){
            Sbytes += String.format("%02X", bytes[i]);
        }

        return Sbytes;
    }

    public void showBytes(byte[] bytes){
        System.out.print("\nByte: ");
        for(byte value : bytes){
            System.out.print(Byte.toUnsignedInt(value));
            System.out.print(", ");
        }
    }

    public static BytesTools getINSTANCE() {
        return INSTANCE;
    }
}

