private void printBitmap(Bitmap bitmap) throws IOException {
    // ESC/POS commands for image printing
    byte[] init = {0x1B, 0x40}; // Initialize printer
    outputStream.write(init);

    int width = bitmap.getWidth();
    int height = bitmap.getHeight();

    for (int y = 0; y < height; y += 12) {
        byte[] line = {0x1B, 0x2A, 33, (byte) (width % 256), (byte) (width / 256)}; // Select bit-image mode
        outputStream.write(line);

        for (int x = 0; x < width; x++) {
            byte slice = 0;
            for (int b = 0; b < 8; b++) {
                int yPos = y + b;
                if (yPos < height && bitmap.getPixel(x, yPos) == Color.BLACK) {
                    slice |= (byte) (1 << (7 - b));
                }
            }
            outputStream.write(slice);
        }
        outputStream.write(new byte[]{0x0A}); // Line feed
    }
}
```

